bash -c "source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 -c '
import transformers
# Check various locations for these names
for name in [\"PaddingStrategy\", \"TruncationStrategy\", \"PreTokenizedInput\", \"TextInput\"]:
    found = False
    for mod_name in [\"transformers\", \"transformers.utils\", \"transformers.tokenization_utils_base\"]:
        try:
            mod = __import__(mod_name, fromlist=[name])
            obj = getattr(mod, name, None)
            if obj is not None:
                print(f\"{name} found in {mod_name}\")
                found = True
                break
        except:
            pass
    if not found:
        print(f\"{name} NOT FOUND\")
'"
